import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"北坞秋日游记","description":"","frontmatter":{"title":"北坞秋日游记","date":"2023-09-08T00:00:00.000Z","category":"随笔","tags":["游记"]},"headers":[],"relativePath":"articles/notes/journal/beiwugongyuan.md","filePath":"articles/notes/journal/beiwugongyuan.md","articleMeta":{"updated":"2023-09-08","words":768,"minutes":2}}`),a={name:`articles/notes/journal/beiwugongyuan.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>9月末，北京已经进入了秋天，一早一晚的风凉飕飕的。在一个多云转晴的周末，驱车来到北坞公园，留下了深刻的印象。北坞公园，承载我关于公园的所有幻想。</p><h2 id="大片的金色水稻田" tabindex="-1">大片的金色水稻田 <a class="header-anchor" href="#大片的金色水稻田" aria-label="Permalink to “大片的金色水稻田”">​</a></h2><p><img src="/images/IMG_3177-1774772143165-1.jpg" alt="img" width="1280" height="960"></p><p>从南门进入，映入眼帘的是大片的<strong>水稻田</strong>，西斜的阳光洒下来，黄灿灿的，带来巨大的视觉冲击力。</p><p>置身于水稻田中，渺小、开阔、豁亮，顺着田垄走过，手指轻拂稻穗🌾，脑海里想的是哲学：“人生就像走过一片不能折返的麦田，要选出最大的一穗”，还有“小麦覆陇黄”的诗意。</p><p>稻穗很精致，大自然赋予他们锋利的叶子、饱满的颗粒，也赋予了他们在生态系统中的角色。无论是拥有精致大脑的人类，还是矫健身手的猎豹；无论是生产者还是消费者，都公平的享有自然的鬼斧神工。</p><h2 id="阳光透过整齐树林" tabindex="-1">阳光透过整齐树林 <a class="header-anchor" href="#阳光透过整齐树林" aria-label="Permalink to “阳光透过整齐树林”">​</a></h2><p>穿过稻田，又映入眼帘的，是阳光穿过的密林。整齐的树，矗立在整齐的草地上，端庄而又美丽。</p><p><img src="/images/IMG_3202-1774772158515-4.jpg" alt="IMG_3202-1774772158515-4" width="1280" height="960"></p><p>下午四点的阳光刚刚好，从西面穿越树林，斑驳的光影洒落，带来明暗交错的立体感，焕发生机。我一眼便相中的这个地方，压抑在心中的阴霾一扫而光，十分养眼。</p><h2 id="大草坪" tabindex="-1">大草坪 <a class="header-anchor" href="#大草坪" aria-label="Permalink to “大草坪”">​</a></h2><p>怎么能拒绝公园的大草坪呢？</p><p><img src="/images/IMG_3220-1774772169308-7.jpg" alt="img" width="1280" height="960"></p><p>整齐的草坪，慵懒的步调，闲适的人群。漫步在其中。此行奔波数十里，遇到喜欢的草地，可惜不让踩踏、更不要说立起帐篷，巡回的保安骑着电驴盯着我手上的营地车，十分警惕。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h2><p>何谓天时地利？天时：在多日的阴霾后绽放的秋日暖阳，是北京城天高气爽的初秋。地利：美丽的北坞公园。一起造就了一个美妙的周末下午。希望我不会遗忘此刻的感动与喜悦。</p><p>2023年秋</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};